    private fun slug(raw: String): String =
        raw.lowercase().replace(Regex("""\s+"""), "-").replace(Regex("""[^a-z0-9-]"""), "")

    fun dealSlug(deal: Deal): String = "${slug(deal.category)}-${slug(deal.itemName)}"
}
